input.content:
# Data exfiltration detection rule
# Alerts on suspicious HTTP POST requests to /telemetry/v2/report with exfil header
# and Base64-encoded blob + 64-char hex signature in body
alert http any any -> any any (
  msg:"Data Exfiltration: Telemetry Exfil Pattern Detected";
  flow:established,to_server;
  content:"POST";
  http_method;
  content:"/telemetry/v2/report";
  http_uri;
  content:"X-TLM-Mode|3a| exfil";
  http_header;
  content:"blob=";
  http_client_body;
  pcre:"/blob=([A-Za-z0-9+/\-_]{80,})/";
  content:"sig=";
  http_client_body;
  pcre:"/sig=([0-9a-fA-F]{64})(?:&|$)/";
  classtype:suspicious-login;
  sid:1000001;
  rev:1;
)

